import {FullMath} from "@uniswap/v4-core/src/libraries/FullMath.sol";
import {FixedPoint96} from "@uniswap/v4-core/src/libraries/FixedPoint96.sol";
import {SafeCast} from "@uniswap/v4-core/src/libraries/SafeCast.sol";

/// @notice Provides functions for computing liquidity amounts from token amounts and prices
library LiquidityAmounts {
    using SafeCast for uint256;

    /// @notice Computes the amount of liquidity received for a given amount of token0 and price range
    /// @dev Calculates amount0 * (sqrt(upper) * sqrt(lower)) / (sqrt(upper) - sqrt(lower))
    /// @param sqrtPriceAX96 A sqrt price representing the first tick boundary
    /// @param sqrtPriceBX96 A sqrt price representing the second tick boundary
    /// @param amount0 The amount0 being sent in
    /// @return liquidity The amount of returned liquidity
    function getLiquidityForAmount0(uint160 sqrtPriceAX96, uint160 sqrtPriceBX96, uint256 amount0)
        internal
        pure
        returns (uint128 liquidity)
    {
        unchecked {
            if (sqrtPriceAX96 > sqrtPriceBX96) (sqrtPriceAX96, sqrtPriceBX96) = (sqrtPriceBX96, sqrtPriceAX96);
            uint256 intermediate = FullMath.mulDiv(sqrtPriceAX96, sqrtPriceBX96, FixedPoint96.Q96);
            return FullMath.mulDiv(amount0, intermediate, sqrtPriceBX96 - sqrtPriceAX96).toUint128();
        }
    }

    /// @notice Computes the amount of liquidity received for a given amount of token1 and price range
    /// @dev Calculates amount1 / (sqrt(upper) - sqrt(lower)).
    /// @param sqrtPriceAX96 A sqrt price representing the first tick boundary
    /// @param sqrtPriceBX96 A sqrt price representing the second tick boundary
    /// @param amount1 The amount1 being sent in
    /// @return liquidity The amount of returned liquidity
    function getLiquidityForAmount1(uint160 sqrtPriceAX96, uint160 sqrtPriceBX96, uint256 amount1)
        internal
        pure
        returns (uint128 liquidity)
    {
        unchecked {
            if (sqrtPriceAX96 > sqrtPriceBX96) (sqrtPriceAX96, sqrtPriceBX96) = (sqrtPriceBX96, sqrtPriceAX96);
            return FullMath.mulDiv(amount1, FixedPoint96.Q96, sqrtPriceBX96 - sqrtPriceAX96).toUint128();
        }
    }

    /// @notice Computes the maximum amount of liquidity received for a given amount of token0, token1, the current
    /// pool prices and the prices at the tick boundaries
    /// @param sqrtPriceX96 A sqrt price representing the current pool prices
    /// @param sqrtPriceAX96 A sqrt price representing the first tick boundary
    /// @param sqrtPriceBX96 A sqrt price representing the second tick boundary
    /// @param amount0 The amount of token0 being sent in
    /// @param amount1 The amount of token1 being sent in
    /// @return liquidity The maximum amount of liquidity received
    function getLiquidityForAmounts(
        uint160 sqrtPriceX96,
        uint160 sqrtPriceAX96,
        uint160 sqrtPriceBX96,
        uint256 amount0,
        uint256 amount1
    ) internal pure returns (uint128 liquidity) {
        if (sqrtPriceAX96 > sqrtPriceBX96) (sqrtPriceAX96, sqrtPriceBX96) = (sqrtPriceBX96, sqrtPriceAX96);

        if (sqrtPriceX96 <= sqrtPriceAX96) {
            liquidity = getLiquidityForAmount0(sqrtPriceAX96, sqrtPriceBX96, amount0);
        } else if (sqrtPriceX96 < sqrtPriceBX96) {
            uint128 liquidity0 = getLiquidityForAmount0(sqrtPriceX96, sqrtPriceBX96, amount0);
            uint128 liquidity1 = getLiquidityForAmount1(sqrtPriceAX96, sqrtPriceX96, amount1);

            liquidity = liquidity0 < liquidity1 ? liquidity0 : liquidity1;
        } else {
            liquidity = getLiquidityForAmount1(sqrtPriceAX96, sqrtPriceBX96, amount1);
        }
    }
}

contracts/pancake-v1/bnb/BnbInfinityLaun.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {OwnableUpgradeable} from "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import {UUPSUpgradeable} from "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {PancakeV1InfinityLaunchEngine} from "../PancakeV1InfinityLaunchEngine.sol";
import {PancakeV1FeeSharingVault} from "../PancakeV1FeeSharingVault.sol";
import {V1PoolId} from "../PancakeV1Interfaces.sol";
import {IInfinityNftModule} from "../PancakeV1LaunchpadInfinityNftUpgradeable.sol";

interface IBnbGraph {
    function launchpad() external view returns (address);
    function engine() external view returns (address);
}

/// @notice Fresh BNB UUPS entrypoint, NOT an upgrade for a Robinhood proxy.
/// Standard and upgradeable NFT rewards share this entrypoint and protocol vault.
/// No no-hook, V1/V2, oracle, USDG, or Robinhood entrypoints are inherited.
contract BnbInfinityLaunchpad is OwnableUpgradeable, UUPSUpgradeable {
    using SafeERC20 for IERC20;
    struct PoolRecord {
        address quoteToken; uint16 weightBps; V1PoolId poolId; uint256 positionId;
        uint256 projectAmount; int24 tickLower; int24 tickUpper; uint256 quotePriceE8; uint8 quoteDecimals;
    }
    struct Allocation { address quoteToken; uint16 weightBps; }
    struct Params {
        bytes identityData; Allocation[] allocations; bytes[] openingData;
        uint256 deadline; bytes32 userSalt; bool sniperProtection; uint256 protectionBlocks;
        uint8 mode; uint16 feeBps; bytes modeData; uint64 policyEffectiveAt; address[] holderExcluded;
    }

    mapping(address => PoolRecord[]) private _pools;
    uint256 public launchFee;
    address public launchFeeRecipient;
    address public socialVerifier;
    address public infinityEngine;
    IInfinityNftModule public nftModule;
    address public directQuoteCoordinator;
    address public nftDirectQuoteCoordinator;
    bool public graphFrozen;
    bool public paused;
    uint256 private _entered;

    error InvalidConfiguration();
    error Unavailable();
    event GraphFrozen(address engine, address nftModule);
    event PauseChanged(bool paused);

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() { _disableInitializers(); }
    function initialize(address admin, address treasury, address verifier, uint256 fee) external initializer {
        if (block.chainid != 56 || admin == address(0) || treasury == address(0)
            || verifier == address(0)) revert InvalidConfiguration();
        __Ownable_init(admin);
        launchFee = fee; launchFeeRecipient = treasury; socialVerifier = verifier;
        paused = true;
    }
    function _authorizeUpgrade(address) internal override onlyOwner {}
    function poolManager() external pure returns (address) {
        return 0xa0FfB9c1CE1Fe56963B0321B32E7A0302114058b;
    }
    function pools(address token) external view returns (PoolRecord[] memory) { return _pools[token]; }

    /// Bind only after reciprocal factory/hook/adapters have been frozen.
    function finalizeGraph(address engine, IInfinityNftModule module,
        address direct, address nftDirect) external onlyOwner {
        if (graphFrozen || engine.code.length == 0
            || !PancakeV1InfinityLaunchEngine(engine).validateLaunchpad(address(this))
            || direct.code.length == 0 || IBnbGraph(direct).launchpad() != address(this))
            revert InvalidConfiguration();
        if (address(module) != address(0)) {
            if (address(module).code.length == 0 || module.launchpad() != address(this)
                || nftDirect.code.length == 0 || IBnbGraph(nftDirect).launchpad() != address(this)
                || IBnbGraph(nftDirect).engine() != address(module)) revert InvalidConfiguration();
        } else if (nftDirect != address(0)) revert InvalidConfiguration();
        infinityEngine = engine; nftModule = module; directQuoteCoordinator = direct;
        nftDirectQuoteCoordinator = nftDirect; graphFrozen = true;
        emit GraphFrozen(engine, address(module));
    }
    function setPaused(bool value) external onlyOwner {
        if (!value && !graphFrozen) revert InvalidConfiguration();
        paused = value; emit PauseChanged(value);
    }
    modifier available() {
        if (paused || !graphFrozen || _entered != 0) revert Unavailable();
        _entered = 1; _; _entered = 0;
    }
    function _validate(bytes memory encoded) private view returns (uint8 mode) {
        Params memory p = abi.decode(encoded, (Params));
        if (keccak256(encoded) != keccak256(abi.encode(p)) || p.mode > 5
            || p.sniperProtection || p.protectionBlocks != 0 || p.policyEffectiveAt != 0
            || p.deadline < block.timestamp || p.deadline > type(uint48).max)
            revert InvalidConfiguration();
        if (p.mode == 3) {
            (, address verifier) = abi.decode(p.modeData, (PancakeV1FeeSharingVault.Recipient[], address));
            if (verifier != socialVerifier) revert InvalidConfiguration();
        }
        if (p.mode == 5 && address(nftModule) == address(0)) revert Unavailable();
        return p.mode;
    }
    function launchInfinity(bytes calldata encoded) external payable available returns (address token) {
        token = _launch(msg.sender, encoded);
    }
    function launchInfinityFor(address creator, bytes calldata encoded)
        external payable available returns (address token) {
        if (msg.sender != directQuoteCoordinator || creator == address(0) || _validate(encoded) == 5)
            revert InvalidConfiguration();
        token = _launch(creator, encoded);
    }
    function launchInfinityNftFor(address creator, bytes calldata encoded)
        external payable available returns (address token) {
        if (msg.sender != nftDirectQuoteCoordinator || creator == address(0) || _validate(encoded) != 5)
            revert InvalidConfiguration();
        token = _launch(creator, encoded);
    }
    function _launch(address creator, bytes memory encoded) private returns (address token) {
        if (_validate(encoded) == 5) return nftModule.launch{value: msg.value}(creator, encoded);
        return PancakeV1InfinityLaunchEngine(infinityEngine).launch{value: msg.value}(creator, encoded);
    }
    function launchInfinityAndBuy(bytes calldata encoded)
        external payable available returns (address token, uint256 output) {
        (bytes memory launchData,) = abi.decode(encoded, (bytes, bytes));
        // Buy-only operation is deliberately not a launch entrypoint.
        if (launchData.length == 0) revert InvalidConfiguration();
        if (_validate(launchData) == 5) return nftModule.launchAndBuy{value: msg.value}(msg.sender, encoded);
        return PancakeV1InfinityLaunchEngine(infinityEngine).launchAndBuy{value: msg.value}(msg.sender, encoded);
    }
    function recordInfinityPool(address token, address quote, bytes32 id, uint16 weight) external {
        if (msg.sender != infinityEngine || _entered == 0 || _pools[token].length >= 5)
            revert InvalidConfiguration();
        _pools[token].push(PoolRecord(quote, weight, V1PoolId.wrap(id), 0, 0, 0, 0, 0, 0));
    }
    function releaseInfinityNftSupply(address project) external {
        if (msg.sender != address(nftModule) || _entered == 0 || !nftModule.validateSupply(project))
            revert InvalidConfiguration();
        uint256 amount = 1_000_000_000 ether;
        if (IERC20(project).balanceOf(address(this)) != amount || IERC20(project).totalSupply() != amount)
            revert InvalidConfiguration();
        IERC20(project).safeTransfer(msg.sender, amount);
    }
    function recordInfinityNftPool(address project, address quote, bytes32 id, uint16 weight,
        uint256 positionId, uint256 amount, int24 lower, int24 upper, uint256 price, uint8 decimals) external {
        if (msg.sender != address(nftModule) || _entered == 0 || _pools[project].length >= 5
            || !nftModule.validatePool(project, quote, id, weight, positionId, amount, lower, upper, price, decimals))
            revert InvalidConfiguration();
        _pools[project].push(PoolRecord(quote, weight, V1PoolId.wrap(id), positionId, amount, lower, upper, price, decimals));
    }
}

contracts/pancake-v1/bnb/immutable/BnbIn.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {BnbInfinityLaunchpad} from "../BnbInfinityLaunchpad.sol";
import {IInfinityNftModule} from "../../PancakeV1LaunchpadInfinityNftUpgradeable.sol";

interface IImmutableCutoverGraph {
    function launchpad() external view returns (address);
    function hook() external view returns (address);
    function factory() external view returns (address);
    function engine() external view returns (address);
    function owner() external view returns (address);
    function validateLaunchpad(address) external view returns (bool);
}
interface IImmutableCutoverHook {
    function registrar() external view returns (address);
    function attestor() external view returns (address);
    function owner() external view returns (address);
    function protocolVault() external view returns (address);
    function frozen() external view returns (bool);
}
interface IImmutableCutoverVault {
    function additionalHook(address) external view returns (bool);
}

/// @notice Deployment-specific launchpad implementation for a future-launch-only
/// cutover. All old launchpad storage and ABI remain inherited unchanged.
/// @dev Constructor pins one reviewed old/new graph, not arbitrary mutable setters.
/// Must be installed and activated atomically while paused. No hook, old adapter,
/// existing PoolKey, project policy, pool record or fee balance is rewritten.
contract BnbInfinityImmutableHookCutover is BnbInfinityLaunchpad {
    struct Graph { address engine; address module; address direct; address nftDirect; }
    address public immutable cutoverLaunchpad;
    address public immutable cutoverProtocolVault;
    address private immutable _oldEngine;
    address private immutable _oldModule;
    address private immutable _oldDirect;
    address private immutable _oldNftDirect;
    address private immutable _newEngine;
    address private immutable _newModule;
    address private immutable _newDirect;
    address private immutable _newNftDirect;

    event ImmutableHookGraphActivated(address indexed oldEngine, address indexed newEngine,
        address indexed hook, address nftHook);

    constructor(address launchpad_, address protocolVault_, Graph memory previous, Graph memory next) {
        if (block.chainid != 56 || launchpad_.code.length == 0 || protocolVault_.code.length == 0
            || previous.engine == next.engine || previous.module == next.module
            || previous.direct == next.direct || previous.nftDirect == next.nftDirect)
            revert InvalidConfiguration();
        _validateCode(previous);
        _validateCode(next);
        cutoverLaunchpad = launchpad_;
        cutoverProtocolVault = protocolVault_;
        _oldEngine = previous.engine; _oldModule = previous.module;
        _oldDirect = previous.direct; _oldNftDirect = previous.nftDirect;
        _newEngine = next.engine; _newModule = next.module;
        _newDirect = next.direct; _newNftDirect = next.nftDirect;
    }

    function previousHookGraph() external view returns (Graph memory) {
        return Graph(_oldEngine, _oldModule, _oldDirect, _oldNftDirect);
    }
    function nextHookGraph() external view returns (Graph memory) {
        return Graph(_newEngine, _newModule, _newDirect, _newNftDirect);
    }
    function activateImmutableHooks() external onlyOwner reinitializer(2) {
        if (address(this) != cutoverLaunchpad || !paused || !graphFrozen
            || infinityEngine != _oldEngine || address(nftModule) != _oldModule
            || directQuoteCoordinator != _oldDirect || nftDirectQuoteCoordinator != _oldNftDirect)
            revert InvalidConfiguration();

        IImmutableCutoverGraph standard = IImmutableCutoverGraph(_newEngine);
        IImmutableCutoverGraph nft = IImmutableCutoverGraph(_newModule);
        if (standard.launchpad() != address(this) || !standard.validateLaunchpad(address(this))
            || nft.launchpad() != address(this)
            || IImmutableCutoverGraph(_newDirect).launchpad() != address(this)
            || IImmutableCutoverGraph(_newNftDirect).launchpad() != address(this)
            || IImmutableCutoverGraph(_newNftDirect).engine() != _newModule)
            revert InvalidConfiguration();
        address hook = standard.hook();
        address nftHook = nft.hook();
        if (hook == IImmutableCutoverGraph(_oldEngine).hook()
            || nftHook == IImmutableCutoverGraph(_oldModule).hook() || hook == nftHook)
            revert InvalidConfiguration();
        _validateHook(hook, _newEngine, standard.factory());
        _validateHook(nftHook, _newModule, nft.factory());

        infinityEngine = _newEngine;
        nftModule = IInfinityNftModule(_newModule);
        directQuoteCoordinator = _newDirect;
        nftDirectQuoteCoordinator = _newNftDirect;
        // Preserve paused=true until the exact new/old consumer manifests are
        // published and checked. Unpause is a separately approved action.
        emit ImmutableHookGraphActivated(_oldEngine, _newEngine, hook, nftHook);
    }

    function _validateHook(address hook, address engine, address factory) private view {
        IImmutableCutoverHook candidate = IImmutableCutoverHook(hook);
        if (hook.code.length == 0 || !candidate.frozen() || candidate.owner() != owner()
            || candidate.registrar() != engine || candidate.attestor() != factory
            || candidate.protocolVault() != cutoverProtocolVault
            || !IImmutableCutoverVault(cutoverProtocolVault).additionalHook(hook)
            || IImmutableCutoverGraph(factory).hook() != hook
            || IImmutableCutoverGraph(factory).engine() != engine)
            revert InvalidConfiguration();
        // Exact immutable-hook bytecode/constructor matching is enforced by the
        // release preflight. A self-reported "immutable" flag is not evidence.
    }

    function _validateCode(Graph memory graph) private view {
        if (graph.engine.code.length == 0 || graph.module.code.length == 0
            || graph.direct.code.length == 0 || graph.nftDirect.code.length == 0)
            revert InvalidConfiguration();
    }
}

contracts/pancake-v1/bnb/standard/BnbInf.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
import {BnbInfinityImmutableHookCutover, IImmutableCutoverGraph, IImmutableCutoverHook}
    from "../immutable/BnbInfinityImmutableHookCutover.sol";
import {IInfinityNftModule} from "../../PancakeV1LaunchpadInfinityNftUpgradeable.sol";

interface IStandardCreditGraph {
    function creditHook(address hook) external view returns(bool);
}
interface IStandardHookVersion {
    function feeAccountingVersion() external view returns(uint8);
}

/// @notice Future-launch cutover after the already-used immutable-hook
/// reinitializer(2). Appends no storage. Old pools/vaults remain untouched.
contract BnbInfinityStandardHookCutover is BnbInfinityImmutableHookCutover {
    constructor(address launchpad_, address protocol_, Graph memory previous, Graph memory next)
        BnbInfinityImmutableHookCutover(launchpad_, protocol_, previous, next) {}

    function activateStandardRouting() external onlyOwner reinitializer(3) {
        Graph memory previous = this.previousHookGraph();
        Graph memory next = this.nextHookGraph();
        if (address(this) != cutoverLaunchpad || !paused || !graphFrozen
            || infinityEngine != previous.engine || address(nftModule) != previous.module
            || directQuoteCoordinator != previous.direct || nftDirectQuoteCoordinator != previous.nftDirect)
            revert InvalidConfiguration();
        IImmutableCutoverGraph standard = IImmutableCutoverGraph(next.engine);
        IImmutableCutoverGraph nft = IImmutableCutoverGraph(next.module);
        if (standard.launchpad() != address(this) || !standard.validateLaunchpad(address(this))
            || nft.launchpad() != address(this)
            || IImmutableCutoverGraph(next.direct).launchpad() != address(this)
            || IImmutableCutoverGraph(next.nftDirect).launchpad() != address(this)
            || IImmutableCutoverGraph(next.nftDirect).engine() != next.module)
            revert InvalidConfiguration();
        address standardHook = standard.hook();
        address nftHook = nft.hook();
        if (standardHook == IImmutableCutoverGraph(previous.engine).hook()
            || nftHook == IImmutableCutoverGraph(previous.module).hook() || standardHook == nftHook)
            revert InvalidConfiguration();
        _validateStandardHook(standardHook, next.engine, standard.factory());
        _validateStandardHook(nftHook, next.module, nft.factory());
        infinityEngine = next.engine;
        nftModule = IInfinityNftModule(next.module);
        directQuoteCoordinator = next.direct;
        nftDirectQuoteCoordinator = next.nftDirect;
        emit ImmutableHookGraphActivated(previous.engine, next.engine, standardHook, nftHook);
        // Deliberately remains paused until dual-release app consumers verify.
    }
    function _validateStandardHook(address hook_, address engine_, address factory_) private view {
        IImmutableCutoverHook candidate = IImmutableCutoverHook(hook_);
        if (!candidate.frozen() || candidate.owner() != owner()
            || candidate.registrar() != engine_ || candidate.attestor() != factory_
            || candidate.protocolVault() != cutoverProtocolVault
            || IStandardHookVersion(hook_).feeAccountingVersion() != 2
            || !IStandardCreditGraph(cutoverProtocolVault).creditHook(hook_)
            || IImmutableCutoverGraph(factory_).hook() != hook_
            || IImmutableCutoverGraph(factory_).engine() != engine_) revert InvalidConfiguration();
    }
}

contracts/pancake-v1/PancakeV1FeeSharing.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ECDSA} from "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

/// @notice Direct final vault for up to five wallet or social recipients.
/// @dev Social identities are opaque provider-scoped keys. The verifier binds
/// an identity to a wallet only at claim time; the vault never calls a social API.
contract PancakeV1FeeSharingVault {
    using SafeERC20 for IERC20;

    uint16 public constant BPS = 10_000;
    uint16 public constant MAX_FEE_BPS = BPS;
    uint8 public constant MAX_RECIPIENTS = 5;
    uint8 public constant MAX_EPOCHS = 64;
    bytes32 public constant CLAIM_TYPEHASH = keccak256(
        "Claim(bytes32 provider,bytes32 identityHash,address wallet,bytes32 assetsHash,uint256 nonce,uint256 deadline)"
    );
    bytes32 private constant DOMAIN_TYPEHASH = keccak256(
        "EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"
    );
    enum Kind { Wallet, Social }
    struct Recipient {
        Kind kind;
        address wallet;
        bytes32 provider;
        bytes32 identityHash;
        uint16 shareBps;
    }
    struct Policy { uint64 activatesAt; uint16 feeBps; uint8 count; }
    address public immutable projectToken;
    address public immutable hook;
    address public immutable admin;
    address public immutable verifier;
    bytes32 private immutable _domainName;
    bytes32 private immutable _domainVersion;
    uint64 public activeEpoch;
    mapping(uint64 => Policy) public policies;
    mapping(uint64 => Recipient[5]) private _recipients;
    mapping(bytes32 => bool) public knownIdentity;
    mapping(uint64 => mapping(address => mapping(address => uint256))) public walletClaimable;
    mapping(uint64 => mapping(bytes32 => mapping(address => uint256))) public socialClaimable;
    mapping(bytes32 => uint256) public nonces;
    mapping(address => uint256) public accrued;
    mapping(address => uint256) public claimed;

    error OnlyHook();
    error OnlyAdmin();
    error InvalidConfiguration();
    error InvalidAuthorization();
    error ExpiredAuthorization();
    error NoClaim();
    error InsufficientRecordedBalance();

    event PolicyAppended(uint64 indexed epoch, uint64 activatesAt, uint16 feeBps);
    event FeeRecorded(uint64 indexed epoch, address indexed asset, uint256 amount);
    event FeeClaimed(address indexed recipient, address indexed asset, uint256 amount);
    event SocialClaimed(
        bytes32 indexed provider, bytes32 indexed identityHash, address indexed wallet,
        address asset, uint256 amount, uint256 nonce
    );

    modifier onlyAdmin() {
        if (msg.sender != admin) revert OnlyAdmin();
        _;
    }

    constructor(address project_, address hook_, address admin_, address verifier_,
        Recipient[] memory recipients_, uint16 feeBps_) {
        if (project_ == address(0) || hook_ == address(0) || admin_ == address(0)
            || verifier_ == address(0) || recipients_.length == 0 || recipients_.length > MAX_RECIPIENTS
            || feeBps_ > MAX_FEE_BPS) revert InvalidConfiguration();
        projectToken = project_;
        hook = hook_;
        admin = admin_;
        verifier = verifier_;
        _domainName = keccak256("PAIR Pancake V1 Fee Sharing");
        _domainVersion = keccak256("1");
        _append(0, recipients_, feeBps_);
    }

    function recipientCount(uint64 epoch) external view returns (uint256) { return policies[epoch].count; }
    function recipient(uint64 epoch, uint256 index) external view returns (Recipient memory) {
        return _recipients[epoch][index];
    }
    function policy(uint64 epoch) external view returns (Policy memory) { return policies[epoch]; }
    function identityNonce(bytes32 provider, bytes32 identityHash) external view returns (uint256) {
        return nonces[_identityKey(provider, identityHash)];
    }

    function appendPolicy(Recipient[] calldata recipients_, uint16 feeBps_, uint64 activatesAt)
        external onlyAdmin {
        // A matured queued policy must become the active epoch before selecting
        // the next slot, otherwise a second append could overwrite it.
        _sync();
        if (activeEpoch >= MAX_EPOCHS || policies[activeEpoch + 1].count != 0) revert InvalidConfiguration();
        if (feeBps_ > MAX_FEE_BPS || recipients_.length == 0 || recipients_.length > MAX_RECIPIENTS) {
            revert InvalidConfiguration();
        }
        if (activatesAt < policies[activeEpoch].activatesAt) revert InvalidConfiguration();
        _append(activatesAt, recipients_, feeBps_);
    }

    function _append(uint64 activatesAt, Recipient[] memory recipients_, uint16 feeBps_) private {
        uint64 epoch = uint64(activeEpoch + 1);
        uint256 total;
        for (uint256 i; i < recipients_.length; ++i) {
            Recipient memory r = recipients_[i];
            bytes32 key = _validateRecipient(r);
            if (_hasDuplicate(recipients_, i, r.kind, key)) revert InvalidConfiguration();
            if (r.kind == Kind.Social) knownIdentity[key] = true;
            _recipients[epoch][i] = r;
            total += r.shareBps;
        }
        if (total != BPS) revert InvalidConfiguration();
        policies[epoch] = Policy(activatesAt, feeBps_, uint8(recipients_.length));
        if (activatesAt <= block.timestamp) activeEpoch = epoch;
        emit PolicyAppended(epoch, activatesAt, feeBps_);
    }

    function _validateRecipient(Recipient memory r) private pure returns (bytes32 key) {
        if (r.kind == Kind.Wallet) {
            if (r.wallet == address(0) || r.shareBps == 0) revert InvalidConfiguration();
            return bytes32(uint256(uint160(r.wallet)));
        }
        key = _identityKey(r.provider, r.identityHash);
        if (r.shareBps == 0) revert InvalidConfiguration();
    }

    function _hasDuplicate(Recipient[] memory recipients_, uint256 index, Kind kind, bytes32 key)
        private pure returns (bool) {
        for (uint256 j; j < index; ++j) {
            Recipient memory prior = recipients_[j];
            bytes32 priorKey = prior.kind == Kind.Wallet
                ? bytes32(uint256(uint160(prior.wallet)))
                : keccak256(abi.encode(prior.provider, prior.identityHash));
            if (prior.kind == kind && priorKey == key) return true;
        }
        return false;
    }

    function _sync() private returns (uint64 epoch) {
        epoch = activeEpoch;
        uint64 next = epoch + 1;
        while (next <= MAX_EPOCHS && policies[next].count != 0 && policies[next].activatesAt <= block.timestamp) {
            epoch = next++;
        }
        activeEpoch = epoch;
    }

    function currentPolicy() external view returns (uint64 epoch, uint16 feeBps) {
        epoch = activeEpoch;
        uint64 next = epoch + 1;
        while (next <= MAX_EPOCHS && policies[next].count != 0 && policies[next].activatesAt <= block.timestamp) ++next;
        return (next - 1, policies[next - 1].feeBps);
    }

    function recordFee(address asset, uint256 amount) external {
        if (msg.sender != hook) revert OnlyHook();
        if (asset == address(0) || amount == 0) revert InvalidConfiguration();
        uint256 outstanding = accrued[asset] - claimed[asset];
        if (_backedBalance(asset) < outstanding + amount) revert InsufficientRecordedBalance();
        uint64 epoch = _sync();
        Policy memory p = policies[epoch];
        uint256 allocated;
        for (uint256 i; i < p.count; ++i) {
            Recipient memory r = _recipients[epoch][i];
            uint256 share = i + 1 == p.count ? amount - allocated : amount * r.shareBps / BPS;
            allocated += share;
            if (r.kind == Kind.Wallet) walletClaimable[epoch][r.wallet][asset] += share;
            else socialClaimable[epoch][_identityKey(r.provider, r.identityHash)][asset] += share;
        }
        accrued[asset] += amount;
        emit FeeRecorded(epoch, asset, amount);
    }

    function claimWallet(address[] calldata assets) external returns (uint256 total) {
        if (assets.length == 0 || assets.length > 20) revert InvalidConfiguration();
        for (uint256 a; a < assets.length; ++a) {
            address asset = assets[a];
            if (asset == address(0)) revert InvalidConfiguration();
            uint256 amount = _takeWallet(msg.sender, asset);
            if (amount != 0) {
                claimed[asset] += amount;
                _beforePayout(asset);
                IERC20(asset).safeTransfer(msg.sender, amount);
                emit FeeClaimed(msg.sender, asset, amount);
                total += amount;
            }
        }
        if (total == 0) revert NoClaim();
    }

    function claimSocial(bytes32 provider, bytes32 identityHash, address wallet, address[] calldata assets,
        uint256 deadline, bytes calldata signature) external returns (uint256 total) {
        bytes32 identityKey = _identityKey(provider, identityHash);
        if (!knownIdentity[identityKey] || wallet == address(0) || assets.length == 0 || assets.length > 20) {
            revert InvalidConfiguration();
        }
        if (block.timestamp > deadline) revert ExpiredAuthorization();
        uint256 nonce = _consumeAuthorization(provider, identityHash, wallet, assets, deadline, signature);
        for (uint256 a; a < assets.length; ++a) {
            address asset = assets[a];
            uint256 amount = _takeSocial(identityKey, asset);
            if (amount != 0) {
                claimed[asset] += amount;
                _beforePayout(asset);
                IERC20(asset).safeTransfer(wallet, amount);
                emit SocialClaimed(provider, identityHash, wallet, asset, amount, nonce);
                total += amount;
            }
        }
        if (total == 0) revert NoClaim();
    }

    function _consumeAuthorization(bytes32 provider, bytes32 identityHash, address wallet, address[] calldata assets,
        uint256 deadline, bytes calldata signature) private returns (uint256 nonce) {
        bytes32 identityKey = _identityKey(provider, identityHash);
        nonce = nonces[identityKey];
        bytes32 assetsHash = keccak256(abi.encode(assets));
        bytes32 structHash = keccak256(
            abi.encode(CLAIM_TYPEHASH, provider, identityHash, wallet, assetsHash, nonce, deadline)
        );
        bytes32 digest = keccak256(abi.encodePacked("\x19\x01", _domainSeparator(), structHash));
        if (ECDSA.recover(digest, signature) != verifier) revert InvalidAuthorization();
        nonces[identityKey] = nonce + 1;
    }

    function _takeWallet(address wallet, address asset) private returns (uint256 amount) {
        for (uint64 e = 1; e <= MAX_EPOCHS; ++e) {
            amount += walletClaimable[e][wallet][asset];
            walletClaimable[e][wallet][asset] = 0;
        }
    }

    function _takeSocial(bytes32 identityKey, address asset) private returns (uint256 amount) {
        for (uint64 e = 1; e <= MAX_EPOCHS; ++e) {
            amount += socialClaimable[e][identityKey][asset];
            socialClaimable[e][identityKey][asset] = 0;
        }
    }

    function _identityKey(bytes32 provider, bytes32 identityHash) private pure returns (bytes32) {
        if (provider == bytes32(0) || identityHash == bytes32(0)) revert InvalidConfiguration();
        return keccak256(abi.encode(provider, identityHash));
    }

    function _domainSeparator() private view returns (bytes32) {
        return keccak256(abi.encode(DOMAIN_TYPEHASH, _domainName, _domainVersion, block.chainid, address(this)));
    }
    function _backedBalance(address asset) internal view virtual returns (uint256) {
        return IERC20(asset).balanceOf(address(this));
    }
    function _beforePayout(address) internal virtual {}
}

contracts/pancake-v1/PancakeV1HolderDist.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/// @notice Keeperless cumulative quote-fee distribution for a PAIR token.
/// @dev The project token must call checkpoint before each balance update.
contract PancakeV1HolderDistributionVault {
    using SafeERC20 for IERC20;

    uint256 public constant MAGNITUDE = 2 ** 128;
    uint256 public constant MAX_ASSETS = 5;
    address public constant DEAD = 0x000000000000000000000000000000000000dEaD;
    address public immutable projectToken;
    address public immutable hook;
    address public immutable registrar;
    mapping(address => bool) public excluded;
    address[] private _assets;
    mapping(address => bool) public registeredAsset;
    uint256 public eligibleSupply;
    mapping(address => uint256) public magnifiedFeePerShare;
    mapping(address => uint256) public magnifiedRemainder;
    mapping(address => uint256) public pending;
    mapping(address => uint256) public accrued;
    mapping(address => uint256) public claimed;
    mapping(address => mapping(address => int256)) private _correction;
    mapping(address => mapping(address => uint256)) public withdrawn;

    error OnlyHook();
    error OnlyRegistrar();
    error OnlyProjectToken();
    error InvalidConfiguration();
    error NoClaim();
    error InsufficientRecordedBalance();

    event AssetRegistered(address indexed asset);
    event FeeRecorded(address indexed asset, uint256 amount, uint256 eligibleSupply);
    event Checkpoint(address indexed from, address indexed to, uint256 amount, uint256 eligibleSupply);
    event FeeClaimed(address indexed holder, address indexed asset, uint256 amount);

    constructor(address project_, address hook_, address registrar_, address[] memory excluded_) {
        if (project_ == address(0) || hook_ == address(0) || registrar_ == address(0) || excluded_.length > 32) {
            revert InvalidConfiguration();
        }
        projectToken = project_;
        hook = hook_;
        registrar = registrar_;
        excluded[address(0)] = true;
        excluded[address(this)] = true;
        excluded[DEAD] = true;
        for (uint256 i; i < excluded_.length; ++i) {
            if (excluded_[i] == address(0) || excluded_[i] == project_ || excluded[excluded_[i]]) {
                revert InvalidConfiguration();
            }
            excluded[excluded_[i]] = true;
        }
    }

    function assetCount() external view returns (uint256) { return _assets.length; }
    function assetAt(uint256 index) external view returns (address) { return _assets[index]; }

    function registerAsset(address asset) external {
        if (msg.sender != registrar && msg.sender != hook) revert OnlyRegistrar();
        if (asset == address(0) || registeredAsset[asset] || _assets.length >= MAX_ASSETS) {
            revert InvalidConfiguration();
        }
        registeredAsset[asset] = true;
        _assets.push(asset);
        emit AssetRegistered(asset);
    }

    function recordFee(address asset, uint256 amount) external {
        if (msg.sender != hook) revert OnlyHook();
        if (!registeredAsset[asset] || amount == 0) revert InvalidConfiguration();
        uint256 outstanding = accrued[asset] - claimed[asset];
        if (_backedBalance(asset) < outstanding + amount) {
            revert InsufficientRecordedBalance();
        }
        accrued[asset] += amount;
        if (eligibleSupply == 0) pending[asset] += amount;
        else _distribute(asset, amount);
        emit FeeRecorded(asset, amount, eligibleSupply);
    }

    function checkpoint(address from, address to, uint256 amount) external {
        if (msg.sender != projectToken) revert OnlyProjectToken();
        if (amount == 0 || from == to) return;
        bool fromEligible = !excluded[from];
        bool toEligible = !excluded[to];
        if (fromEligible) {
            if (eligibleSupply < amount) revert InvalidConfiguration();
            eligibleSupply -= amount;
        }
        if (toEligible) eligibleSupply += amount;
        for (uint256 i; i < _assets.length; ++i) {
            address asset = _assets[i];
            uint256 mps = magnifiedFeePerShare[asset];
            if (fromEligible) _correction[asset][from] += int256(mps * amount);
            if (toEligible) _correction[asset][to] -= int256(mps * amount);
            if (eligibleSupply != 0 && pending[asset] != 0) {
                uint256 deferred = pending[asset];
                pending[asset] = 0;
                _distribute(asset, deferred);
            }
        }
        emit Checkpoint(from, to, amount, eligibleSupply);
    }

    function _distribute(address asset, uint256 amount) private {
        uint256 numerator = amount * MAGNITUDE + magnifiedRemainder[asset];
        magnifiedFeePerShare[asset] += numerator / eligibleSupply;
        magnifiedRemainder[asset] = numerator % eligibleSupply;
    }

    function withdrawableOf(address holder, address asset) public view returns (uint256) {
        if (excluded[holder] || !registeredAsset[asset]) return 0;
        int256 value = int256(magnifiedFeePerShare[asset] * IERC20(projectToken).balanceOf(holder))
            + _correction[asset][holder];
        if (value <= 0) return 0;
        uint256 total = uint256(value) / MAGNITUDE;
        return total > withdrawn[asset][holder] ? total - withdrawn[asset][holder] : 0;
    }

    function correctionOf(address holder, address asset) external view returns (int256) {
        return _correction[asset][holder];
    }

    function claimMany(address[] calldata assets) external returns (uint256 total) {
        if (assets.length == 0 || assets.length > MAX_ASSETS) revert InvalidConfiguration();
        for (uint256 i; i < assets.length; ++i) {
            address asset = assets[i];
            uint256 amount = withdrawableOf(msg.sender, asset);
            if (amount != 0) {
                withdrawn[asset][msg.sender] += amount;
                claimed[asset] += amount;
                _beforePayout(asset);
                IERC20(asset).safeTransfer(msg.sender, amount);
                emit FeeClaimed(msg.sender, asset, amount);
                total += amount;
            }
        }
        if (total == 0) revert NoClaim();
    }
    function _backedBalance(address asset) internal view virtual returns (uint256) {
        return IERC20(asset).balanceOf(address(this));
    }
    function _beforePayout(address) internal virtual {}
}

