// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @notice Narrow ABI-compatible Pancake Infinity CL types.  These are
/// intentionally vendored because the application does not pin the upstream
/// Infinity package as a Solidity dependency.
type PancakeV1Currency is address;
type PancakeV1BeforeSwapDelta is int256;
type PancakeV1BalanceDelta is int256;

interface IPancakeV1Hooks {
    function getHooksRegistrationBitmap() external view returns (uint16);
}

interface IPancakeV1CLPoolManager {
    struct SwapParams {
        bool zeroForOne;
        int256 amountSpecified;
        uint160 sqrtPriceLimitX96;
    }

    function vault() external view returns (address);
    function getSlot0(bytes32 poolId)
        external view returns (uint160 sqrtPriceX96, int24 tick, uint24 protocolFee, uint24 lpFee);
    function swap(
        PancakeV1PoolKey calldata key,
        SwapParams calldata params,
        bytes calldata hookData
    ) external returns (PancakeV1BalanceDelta delta);
}

interface IPancakeV1Vault {
    function manager() external view returns (address);
    function lock(bytes calldata data) external returns (bytes memory);
    function currencyDelta(address settler, PancakeV1Currency currency) external view returns (int256);
    function getUnsettledDeltasCount() external view returns (uint256);
    function sync(PancakeV1Currency currency) external;
    function settleFor(address recipient) external payable returns (uint256);
    function take(PancakeV1Currency currency, address to, uint256 amount) external;
}

interface IPancakeV1LockCallback {
    function lockAcquired(bytes calldata data) external returns (bytes memory);
}

interface IPancakeV1FeeReceiver {
    function recordFee(address asset, uint256 amount) external;
}

struct PancakeV1PoolKey {
    PancakeV1Currency currency0;
    PancakeV1Currency currency1;
    IPancakeV1Hooks hooks;
    IPancakeV1CLPoolManager poolManager;
    uint24 fee;
    bytes32 parameters;
}

library PancakeV1BalanceDeltaLib {
    function amount0(PancakeV1BalanceDelta delta) internal pure returns (int128 value) {
        assembly ("memory-safe") { value := sar(128, delta) }
    }

    function amount1(PancakeV1BalanceDelta delta) internal pure returns (int128 value) {
        assembly ("memory-safe") { value := signextend(15, delta) }
    }
}

library PancakeV1BeforeSwapDeltaLib {
    function toDelta(int128 specified, int128 unspecified)
        internal pure returns (PancakeV1BeforeSwapDelta value) {
        assembly ("memory-safe") {
            value := or(shl(128, specified), and(sub(shl(128, 1), 1), unspecified))
        }
    }
}

contracts/pancake-v1/PancakeV1InfinityLa.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IERC20Metadata} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import {TickMath} from "@uniswap/v4-core/src/libraries/TickMath.sol";
import {PancakeV1InfinityLaunchFactory} from "./PancakeV1InfinityLaunchFactory.sol";
import {PancakeV1InfinityPoolBootstrapper} from "./PancakeV1InfinityPoolBootstrapper.sol";
import {PancakeV1FeeSharingVault} from "./PancakeV1FeeSharingVault.sol";
import {IPancakeV1Hooks, IPancakeV1CLPoolManager, PancakeV1PoolKey, PancakeV1Currency} from "./PancakeV1InfinityHookTypes.sol";

interface IPancakeV1InfinityLaunchpad {
    function launchFee() external view returns (uint256);
    function launchFeeRecipient() external view returns (address);
    function poolManager() external view returns (address);
    function positionManager() external view returns (address);
    function permit2() external view returns (address);
    function infinityApprove(address token, uint256 amount, uint256 deadline) external;
    function recordInfinityPool(address,address,bytes32,uint16) external;
    function modeVault(address project, uint8 mode, bytes calldata modeData, uint16 feeBps)
        external returns (address);
}
interface IPancakeV1Permit2 {
    function approve(address token, address spender, uint160 amount, uint48 expiration) external;
}

interface IPancakeV1InfinityHookEngine {
    enum FeeMode { NONE, CREATOR_QUOTE, BURN_PROJECT, FEE_SHARING_QUOTE, HOLDER_QUOTE }
    function getHooksRegistrationBitmap() external view returns (uint16);
    function schedulePolicy(address, FeeMode, uint16, address, uint64) external returns (uint64);
    function registerPool(PancakeV1PoolKey calldata,address,address,uint160,bool) external;
    function poolManager() external view returns(address);
    function registrar() external view returns(address);
    function owner() external view returns(address);
    function frozen() external view returns(bool);
}
interface IPancakeV1InfinityDeveloperBuy {
    function launchpad() external view returns(address);
    function engine() external view returns(address);
    function poolManager() external view returns(address);
    function hook() external view returns(address);
    function execute(address project, address payer, uint256 launchDeadline, bytes calldata encodedPlan)
        external payable returns (uint256);
}

/// @notice Immutable ordinary-call orchestrator. It never owns launch tokens:
/// the launchpad proxy remains the ERC20 owner and approves Infinity Permit2
/// through its engine-only gateway for each mint.
contract PancakeV1InfinityLaunchEngine {
    using SafeERC20 for IERC20;
    address public immutable launchpad;
    PancakeV1InfinityLaunchFactory public immutable factory;
    PancakeV1InfinityPoolBootstrapper public immutable bootstrapper;
    IPancakeV1InfinityHookEngine public immutable hook;
    IPancakeV1InfinityDeveloperBuy public immutable developerBuyExecutor;

    struct Allocation { address quoteToken; uint16 weightBps; }
    struct Params {
        bytes identityData;
        Allocation[] allocations;
        bytes[] openingData;
        uint256 deadline;
        bytes32 userSalt;
        bool sniperProtection;
        uint256 protectionBlocks;
        IPancakeV1InfinityHookEngine.FeeMode mode;
        uint16 feeBps;
        bytes modeData;
        uint64 policyEffectiveAt;
        address[] holderExcluded;
    }
    struct Opening {
        uint8 decimals; uint160 opening; int24 lower; int24 upper; uint256 observed;
        bytes32 evidence; uint160 graduation; bool above;
    }

    error OnlyLaunchpad();
    error InvalidLaunch();
    error InvalidGraduation();
    error DeveloperBuyUnavailable();

    constructor(address launchpad_, PancakeV1InfinityLaunchFactory factory_,
        PancakeV1InfinityPoolBootstrapper bootstrapper_, IPancakeV1InfinityHookEngine hook_,
        IPancakeV1InfinityDeveloperBuy buyExecutor_) {
        if (launchpad_ == address(0) || address(factory_).code.length == 0
            || address(bootstrapper_).code.length == 0 || address(hook_).code.length == 0
            || address(buyExecutor_) == address(0)
            || factory_.tokenLaunchpad() != launchpad_
            || address(bootstrapper_.hook()) != address(hook_)
            || address(hook_.poolManager()) != address(IPancakeV1InfinityLaunchpad(launchpad_).poolManager())
            || buyExecutor_.launchpad() != launchpad_
            || (buyExecutor_.engine() != address(0) && buyExecutor_.engine() != address(this))
            || buyExecutor_.poolManager() != address(hook_.poolManager())
            || buyExecutor_.hook() != address(hook_)) revert InvalidLaunch();
        launchpad = launchpad_; factory = factory_; bootstrapper = bootstrapper_; hook = hook_;
        developerBuyExecutor = buyExecutor_;
    }

    /// @notice Reciprocal graph attestation used by the storage-safe
    /// launchpad successor initializer.
    function validateLaunchpad(address launchpad_) external view returns (bool) {
        return launchpad_ == launchpad && factory.validateGraph(launchpad_, address(this))
            && address(hook).code.length != 0 && hook.frozen()
            && hook.registrar() == address(this);
    }

    function launch(address creator, bytes calldata encoded) external payable returns (address token) {
        if (msg.sender != launchpad || creator == address(0)) revert OnlyLaunchpad();
        uint256 fee = IPancakeV1InfinityLaunchpad(launchpad).launchFee();
        if (msg.value != fee) revert InvalidLaunch();
        (token,) = _launch(creator, encoded, fee);
    }

    function launchAndBuy(address creator, bytes calldata encoded)
        external payable returns (address token, uint256 projectAmountOut) {
        if (msg.sender != launchpad || creator == address(0)
            || address(developerBuyExecutor) == address(0)) revert DeveloperBuyUnavailable();
        (bytes memory launchEncoded, bytes memory buyEncoded) = abi.decode(encoded, (bytes, bytes));
        if (launchEncoded.length == 0) {
            (token, buyEncoded) = abi.decode(buyEncoded, (address, bytes));
            projectAmountOut = developerBuyExecutor.execute{value: msg.value}(
                token, creator, block.timestamp + 30 minutes, buyEncoded);
            return (token, projectAmountOut);
        }
        uint256 fee = IPancakeV1InfinityLaunchpad(launchpad).launchFee();
        if (msg.value <= fee) revert InvalidLaunch();
        uint256 launchDeadline;
        (token, launchDeadline) = _launch(creator, launchEncoded, fee);
        projectAmountOut = developerBuyExecutor.execute{value: msg.value - fee}(
            token, creator, launchDeadline, buyEncoded);
    }

    function _launch(address creator, bytes memory encoded, uint256 fee)
        internal returns (address token, uint256 launchDeadline) {
        if (!factory.frozen() || !hook.frozen() || factory.engine() != address(this)
            || hook.registrar() != address(this)) revert InvalidLaunch();
        Params memory p = abi.decode(encoded, (Params));
        if (block.timestamp > p.deadline || p.allocations.length == 0
            || p.allocations.length > 5 || p.openingData.length != p.allocations.length) revert InvalidLaunch();
        launchDeadline = p.deadline;
        (string memory name, string memory symbol, string memory uri, bytes32 hash) =
            abi.decode(p.identityData, (string,string,string,bytes32));
        PancakeV1InfinityLaunchFactory.Identity memory identity =
            PancakeV1InfinityLaunchFactory.Identity(creator,name,symbol,uri,hash);
        uint256 protection = p.sniperProtection ? p.protectionBlocks : 0;
        if ((!p.sniperProtection && p.protectionBlocks != 0) || protection > 64) revert InvalidLaunch();
        address lock; address holderVault;
        if (p.mode == IPancakeV1InfinityHookEngine.FeeMode.HOLDER_QUOTE) {
            (token,lock,holderVault) = factory.deployHolder(identity,p.userSalt,protection,
                p.holderExcluded,_quotes(p.allocations));
            hook.schedulePolicy(token,p.mode,p.feeBps,holderVault,p.policyEffectiveAt);
        } else {
            (token,lock) = factory.deployStandard(identity,p.userSalt,protection);
            address destination;
            if (p.mode == IPancakeV1InfinityHookEngine.FeeMode.CREATOR_QUOTE
                || p.mode == IPancakeV1InfinityHookEngine.FeeMode.FEE_SHARING_QUOTE) {
                destination = _modeVault(token, p);
            } else if (p.mode == IPancakeV1InfinityHookEngine.FeeMode.NONE
                || p.mode == IPancakeV1InfinityHookEngine.FeeMode.BURN_PROJECT) {
                if (p.mode == IPancakeV1InfinityHookEngine.FeeMode.NONE && p.modeData.length != 0
                    || p.mode == IPancakeV1InfinityHookEngine.FeeMode.BURN_PROJECT && p.modeData.length != 0) revert InvalidLaunch();
                destination = p.mode == IPancakeV1InfinityHookEngine.FeeMode.BURN_PROJECT
                    ? address(0x000000000000000000000000000000000000dEaD) : address(0);
            } else revert InvalidLaunch();
            hook.schedulePolicy(token,p.mode,p.feeBps,destination,p.policyEffectiveAt);
        }
        uint256 totalWeight;
        uint256 allocated;
        for (uint256 i; i < p.allocations.length; ++i) {
            totalWeight += p.allocations[i].weightBps;
            if (i != 0 && p.allocations[i].quoteToken <= p.allocations[i-1].quoteToken) revert InvalidLaunch();
            Opening memory o = _opening(p.allocations[i],p.openingData[i]);
            uint256 amount = i + 1 == p.allocations.length ? 1_000_000_000 ether - allocated
                : uint256(1_000_000_000 ether) * uint256(p.allocations[i].weightBps) / 10_000;
            allocated += amount;
            IERC20(token).safeTransfer(address(bootstrapper), amount);
            (bytes32 pid,) = bootstrapper.initializePool(token,p.allocations[i].quoteToken,
                amount,p.deadline,lock,o.opening,o.lower,o.upper,hook.getHooksRegistrationBitmap());
            bool project0 = token < p.allocations[i].quoteToken;
            bytes32 parameters = bytes32(uint256(hook.getHooksRegistrationBitmap())
                | (uint256(uint24(uint24(200))) << 16));
            PancakeV1PoolKey memory key = PancakeV1PoolKey(
                PancakeV1Currency.wrap(project0 ? token : p.allocations[i].quoteToken),
                PancakeV1Currency.wrap(project0 ? p.allocations[i].quoteToken : token),
                IPancakeV1Hooks(address(hook)), IPancakeV1CLPoolManager(IPancakeV1InfinityLaunchpad(launchpad).poolManager()),
                10_000, parameters);
            bool above = token < p.allocations[i].quoteToken;
            if (o.above != above) revert InvalidGraduation();
            hook.registerPool(key,token,p.allocations[i].quoteToken,o.graduation,above);
            IPancakeV1InfinityLaunchpad(launchpad).recordInfinityPool(token,p.allocations[i].quoteToken,
                pid,p.allocations[i].weightBps);
        }
        if (totalWeight != 10_000) revert InvalidLaunch();
        (bool ok,) = payable(IPancakeV1InfinityLaunchpad(launchpad).launchFeeRecipient()).call{value: fee}("");
        if (!ok) revert InvalidLaunch();
    }

    function _opening(Allocation memory a, bytes memory data) private view returns (Opening memory o) {
        (o.decimals,o.opening,o.lower,o.upper,o.observed,o.evidence,o.graduation,o.above) =
            abi.decode(data,(uint8,uint160,int24,int24,uint256,bytes32,uint160,bool));
        uint8 d = IERC20Metadata(a.quoteToken).decimals();
        if (d != o.decimals || o.observed > block.timestamp || block.timestamp-o.observed > 30 minutes
            || o.opening < TickMath.MIN_SQRT_PRICE || o.opening >= TickMath.MAX_SQRT_PRICE
            || o.graduation < TickMath.MIN_SQRT_PRICE || o.graduation >= TickMath.MAX_SQRT_PRICE
            || o.lower >= o.upper || o.lower % 200 != 0 || o.upper % 200 != 0) revert InvalidLaunch();
        uint160 lo=TickMath.getSqrtPriceAtTick(o.lower); uint160 hi=TickMath.getSqrtPriceAtTick(o.upper);
        if (o.opening != lo && o.opening != hi
            || (o.above ? o.graduation <= o.opening : o.graduation >= o.opening)) revert InvalidGraduation();
    }

    function _quotes(Allocation[] memory a) private pure returns (address[] memory q) {
        q = new address[](a.length);
        for (uint256 i; i < a.length; ++i) q[i] = a[i].quoteToken;
    }

    function _modeVault(address token, Params memory p) private returns (address destination) {
        if (p.mode == IPancakeV1InfinityHookEngine.FeeMode.CREATOR_QUOTE) {
            (address recipient) = abi.decode(p.modeData, (address));
            destination = factory.deployCreatorVault(token, recipient, p.feeBps);
        } else {
            (PancakeV1FeeSharingVault.Recipient[] memory recipients, address verifier) =
                abi.decode(p.modeData, (PancakeV1FeeSharingVault.Recipient[], address));
            destination = factory.deploySharingVault(token, recipients, verifier, p.feeBps);
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {PancakeV1HolderToken} from "./PancakeV1HolderToken.sol";
import {PancakeV1InfinityCreationDeployers} from "./PancakeV1InfinityCreationDeployers.sol";
import {PancakeV1HolderDistributionVault} from "./PancakeV1HolderDistributionVault.sol";
import {PancakeV1FeeSharingVault} from "./PancakeV1FeeSharingVault.sol";
interface IPancakeV1InfinityVaultDeployer {
    function admin() external view returns(address);
    function engine() external view returns(address);
    function hook() external view returns(address);
    function creator(address,address,uint16) external returns(address);
    function sharing(address,PancakeV1FeeSharingVault.Recipient[] calldata,address,uint16) external returns(address);
}

interface IPancakeV1InfinityHookFactory {
    function addressOf() external view returns (address);
    function poolManager() external view returns (address);
}
interface IPancakeV1InfinityManager { function vault() external view returns (address); }
interface IPancakeV1InfinityGraphEngine {
    function launchpad() external view returns (address);
    function factory() external view returns (address);
    function hook() external view returns (address);
}

/// @notice CREATE2 factory for the hooked Infinity release. Standard tokens
/// use the existing immutable token; holder launches use a token/vault pair
/// whose vault is bound before the initial mint.
contract PancakeV1InfinityLaunchFactory {
    address public immutable admin;
    address public immutable launchpad;
    address public engine;
    address public immutable tokenLaunchpad;
    address public immutable vault;
    address public immutable positionManager;
    address public immutable hook;
    IPancakeV1InfinityVaultDeployer public immutable vaultDeployer;
    PancakeV1InfinityCreationDeployers public immutable creationDeployers;
    bool public frozen;
    mapping(address => mapping(uint8 => mapping(address => bool))) public attestedVault;

    error OnlyLaunchpad();
    error Occupied();
    error InvalidConfiguration();
    error AttestationAuthority();
    event HolderDeployed(address indexed token, address indexed lock, address indexed holderVault);
    event VaultAttested(address indexed project, uint8 indexed mode, address indexed vault);

    struct Identity {
        address creator;
        string name;
        string symbol;
        string metadataURI;
        bytes32 metadataHash;
    }

    constructor(address admin_, address tokenLaunchpad_, address vault_, address positionManager_, address hook_,
        IPancakeV1InfinityVaultDeployer vaultDeployer_, PancakeV1InfinityCreationDeployers creationDeployers_) {
        if (admin_ == address(0) || tokenLaunchpad_ == address(0) || vault_.code.length == 0 || positionManager_.code.length == 0
            || hook_.code.length == 0 || address(vaultDeployer_).code.length == 0
            || vaultDeployer_.hook() != hook_ || vaultDeployer_.admin() != admin_
            || address(creationDeployers_).code.length == 0 || creationDeployers_.admin() != admin_
            || creationDeployers_.positionManager() != positionManager_) revert InvalidConfiguration();
        admin = admin_;
        launchpad = tokenLaunchpad_;
        tokenLaunchpad = tokenLaunchpad_;
        vault = vault_;
        positionManager = positionManager_;
        hook = hook_;
        vaultDeployer = vaultDeployer_;
        creationDeployers = creationDeployers_;
    }

    function bindEngine(address engine_) external {
        if (msg.sender != admin || frozen || engine_ == address(0) || engine_.code.length == 0) {
            revert AttestationAuthority();
        }
        (bool ok, bytes memory data) = engine_.staticcall(abi.encodeWithSignature("factory()"));
        if (!ok || data.length < 32 || abi.decode(data, (address)) != address(this)) revert InvalidConfiguration();
        (ok, data) = engine_.staticcall(abi.encodeWithSignature("hook()"));
        if (!ok || data.length < 32 || abi.decode(data, (address)) != hook) revert InvalidConfiguration();
        // The protected release coordinator binds these two creation helpers
        // to this factory before this final graph edge is frozen.  Requiring
        // the reciprocal identity here prevents a helper from being swapped
        // after activation without allowing the factory to self-authorize a
        // helper binding.
        if (creationDeployers.engine() != address(this)
            || vaultDeployer.engine() != address(this)) revert InvalidConfiguration();
        engine = engine_;
        frozen = true;
    }

    /// @notice Compact reciprocal graph check consumed by the storage-safe
    /// launchpad successor initializer.
    function validateGraph(address launchpad_, address engine_) external view returns (bool) {
        if (!frozen || engine_ != engine || tokenLaunchpad != launchpad_
            || IPancakeV1InfinityGraphEngine(engine_).launchpad() != launchpad_
            || IPancakeV1InfinityGraphEngine(engine_).factory() != address(this)
            || IPancakeV1InfinityGraphEngine(engine_).hook() != hook
            || creationDeployers.engine() != address(this)
            || vaultDeployer.engine() != address(this)) return false;
        return true;
    }

    function deployStandard(Identity calldata i, bytes32 salt, uint256 protectionBlocks)
        external returns (address token, address lock) {
        if (!frozen || msg.sender != engine) revert OnlyLaunchpad();
        (token, lock) = predictStandard(i, salt, protectionBlocks);
        if (token.code.length != 0 || lock.code.length != 0) revert Occupied();
        lock = creationDeployers.lock(_lockSalt(i));
        Identity memory m = i;
        token = _deployStandardToken(m, salt, lock, protectionBlocks);
    }

    /// @notice Predicts the exact standard Infinity token and lock addresses.
    /// The user salt is creator-bound by _tokenSalt but is otherwise unrestricted:
    /// vanity policy (if any) belongs to the website, never this factory.
    function predictStandard(Identity calldata i, bytes32 salt, uint256 protectionBlocks)
        public view returns (address token, address lock) {
        lock = creationDeployers.predictLock(_lockSalt(i));
        token = creationDeployers.predictStandard(
            _tokenSalt(i.creator, salt), i.name, i.symbol, i.metadataURI, i.metadataHash,
            lock, i.creator, engine, protectionBlocks
        );
    }

    function _deployStandardToken(Identity memory i, bytes32 salt, address lock, uint256 protectionBlocks)
        private returns (address token) {
        return creationDeployers.standard(_tokenSalt(i.creator, salt), i.name, i.symbol, i.metadataURI,
            i.metadataHash, lock, i.creator, engine, protectionBlocks);
    }

    function deployHolder(Identity calldata i, bytes32 salt, uint256 protectionBlocks,
        address[] calldata excluded, address[] calldata assets)
        external returns (address token, address lock, address holderVault) {
        if (!frozen || msg.sender != engine) revert OnlyLaunchpad();
        (token, lock) = predictHolder(i, salt, protectionBlocks);
        if (token.code.length != 0 || lock.code.length != 0) revert Occupied();
        lock = creationDeployers.lock(_lockSalt(i));
        token = _deployHolderToken(i, salt, lock, protectionBlocks);
        holderVault = _deployHolderVault(token, excluded, lock);
        _attest(token, 4, holderVault);
        for (uint256 i; i < assets.length; ++i) {
            PancakeV1HolderDistributionVault(holderVault).registerAsset(assets[i]);
        }
        creationDeployers.bind(token, holderVault);
        emit HolderDeployed(token, lock, holderVault);
    }

    /// @notice Predicts the exact holder-token address before vault binding.
    function predictHolder(Identity calldata i, bytes32 salt, uint256 protectionBlocks)
        public view returns (address token, address lock) {
        lock = creationDeployers.predictLock(_lockSalt(i));
        token = _predictHolderToken(i, salt, lock, protectionBlocks);
    }

    function attestVault(address project, uint8 mode, address vault_) external {
        if (!frozen || msg.sender != engine || project == address(0) || vault_.code.length == 0) revert AttestationAuthority();
        _attest(project, mode, vault_);
    }
    function deployCreatorVault(address project, address recipient, uint16 feeBps)
        external returns (address vault_) {
        if (!frozen || msg.sender != engine || recipient == address(0)) revert AttestationAuthority();
        vault_ = vaultDeployer.creator(project, recipient, feeBps);
        _attest(project, 1, vault_);
    }
    function deploySharingVault(address project, PancakeV1FeeSharingVault.Recipient[] calldata recipients,
        address verifier, uint16 feeBps) external returns (address vault_) {
        if (!frozen || msg.sender != engine || verifier == address(0)) revert AttestationAuthority();
        vault_ = vaultDeployer.sharing(project, recipients, verifier, feeBps);
        _attest(project, 3, vault_);
    }
    function verifyVault(address project, uint8 mode, address vault_) external view returns (bool) {
        return attestedVault[project][mode][vault_];
    }
    function _attest(address project, uint8 mode, address vault_) private {
        if (PancakeV1HolderDistributionVault(vault_).projectToken() != project
            || PancakeV1HolderDistributionVault(vault_).hook() != hook) revert InvalidConfiguration();
        attestedVault[project][mode][vault_] = true;
        emit VaultAttested(project, mode, vault_);
    }

    function _deployHolderToken(Identity calldata i, bytes32 salt, address lock, uint256 protectionBlocks)
        private returns (address token) {
        return creationDeployers.holder(_tokenSalt(i.creator, salt), i.name, i.symbol, i.metadataURI,
            i.metadataHash, lock, i.creator, engine, protectionBlocks);
    }

    function _predictHolderToken(Identity calldata i, bytes32 salt, address lock, uint256 protectionBlocks)
        private view returns (address token) {
        return creationDeployers.predictHolder(_tokenSalt(i.creator, salt), i.name, i.symbol,
            i.metadataURI, i.metadataHash, lock, i.creator, engine, protectionBlocks);
    }

    function _deployHolderVault(address token, address[] calldata excluded, address lock)
        private returns (address) {
        address manager = _manager();
        (bool ok, bytes memory data) = manager.staticcall(
            abi.encodeWithSelector(IPancakeV1InfinityManager.vault.selector));
        address custody = ok && data.length >= 32 ? abi.decode(data, (address)) : manager;
        uint256 count = 1;
        if (manager != engine) ++count;
        if (custody != engine && custody != manager) ++count;
        if (positionManager != engine && positionManager != manager && positionManager != custody) ++count;
        if (lock != engine && lock != manager && lock != custody && lock != positionManager) ++count;
        if (tokenLaunchpad != engine && tokenLaunchpad != manager && tokenLaunchpad != custody && tokenLaunchpad != positionManager && tokenLaunchpad != lock) ++count;
        for (uint256 i; i < excluded.length; ++i) {
            if (!_forced(excluded[i], manager, custody, lock, token) && !_contains(excluded, i, excluded[i])) ++count;
        }
        address[] memory all = new address[](count);
        all[0] = engine;
        uint256 n = 1;
        if (manager != engine) all[n++] = manager;
        if (custody != engine && custody != manager) all[n++] = custody;
        if (positionManager != engine && positionManager != manager && positionManager != custody) all[n++] = positionManager;
        if (lock != engine && lock != manager && lock != custody && lock != positionManager) all[n++] = lock;
        if (tokenLaunchpad != engine && tokenLaunchpad != manager && tokenLaunchpad != custody && tokenLaunchpad != positionManager && tokenLaunchpad != lock) all[n++] = tokenLaunchpad;
        for (uint256 i; i < excluded.length; ++i) {
            if (!_forced(excluded[i], manager, custody, lock, token) && !_contains(excluded, i, excluded[i])) all[n++] = excluded[i];
        }
        return address(new PancakeV1HolderDistributionVault(token, hook, address(this), all));
    }

    function _forced(address a, address manager, address custody, address lock, address token) private view returns (bool) {
        return a == address(0) || a == 0x000000000000000000000000000000000000dEaD
            || a == address(this) || a == engine || a == manager || a == custody || a == positionManager
            || a == lock || a == tokenLaunchpad || a == token;
    }
    function _manager() private view returns (address manager) {
        (bool ok, bytes memory data) = hook.staticcall(abi.encodeWithSelector(
            IPancakeV1InfinityHookFactory.poolManager.selector));
        manager = ok && data.length >= 32 ? abi.decode(data, (address)) : positionManager;
    }
    function _contains(address[] calldata a, uint256 end, address value) private pure returns (bool) {
        for (uint256 i; i < end; ++i) if (a[i] == value) return true;
        return false;
    }

    function predictLock(Identity calldata i) external view returns (address) {
        return creationDeployers.predictLock(_lockSalt(i));
    }

    function _lockSalt(Identity calldata i) private pure returns (bytes32) {
        return keccak256(abi.encode(keccak256("PANCAKE_V1_INFINITY_LOCK"), i.creator, i.name,
            i.symbol, i.metadataURI, i.metadataHash));
    }
    function _tokenSalt(address creator, bytes32 salt) private pure returns (bytes32) {
        return keccak256(abi.encode(keccak256("PANCAKE_V1_INFINITY_TOKEN"), creator, salt));
    }
    function _create2(bytes32 salt, bytes32 hash) private view returns (address) {
        return address(uint160(uint256(keccak256(abi.encodePacked(
            bytes1(0xff), address(this), salt, hash
        )))));
    }
}

contracts/pancake-v1/PancakeV1InfinityPo.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {TickMath} from "@uniswap/v4-core/src/libraries/TickMath.sol";
import {LiquidityAmounts} from "@uniswap/v4-periphery/src/libraries/LiquidityAmounts.sol";
import {IV1PoolManager, IV1Permit2, IV1CLPositionManager, IV1Hooks, V1Currency, V1PoolKey} from "./PancakeV1Interfaces.sol";

contract PancakeV1InfinityPoolBootstrapper {
    using SafeERC20 for IERC20;
    IV1PoolManager public immutable manager;
    IV1CLPositionManager public immutable positions;
    IV1Permit2 public immutable permit2;
    IV1Hooks public immutable hook;
    uint24 public constant FEE = 10_000;
    int24 public constant SPACING = 200;

    constructor(IV1PoolManager manager_, IV1CLPositionManager positions_, IV1Permit2 permit2_, IV1Hooks hook_) {
        if (address(manager_).code.length == 0 || address(positions_).code.length == 0
            || address(permit2_).code.length == 0 || address(hook_).code.length == 0
            || address(manager_.vault()).code.length == 0) revert();
        manager = manager_; positions = positions_; permit2 = permit2_; hook = hook_;
    }

    function initializePool(address token, address quote, uint256 amount, uint256 deadline, address lock,
        uint160 opening, int24 lower, int24 upper, uint16 bitmap)
        external returns (bytes32 pid, uint256 positionId) {
        (bool registrarOk, bytes memory registrarData) = address(hook).staticcall(
            abi.encodeWithSignature("registrar()"));
        if (!registrarOk || registrarData.length < 32
            || abi.decode(registrarData, (address)) != msg.sender) revert("CALLER");
        uint256 beforeBalance = IERC20(token).balanceOf(address(this));
        if (beforeBalance != amount) revert("FUNDING");
        permit2.approve(token, address(positions), uint160(amount), uint48(deadline));
        IERC20(token).forceApprove(address(permit2), amount);
        bool projectIs0 = token < quote;
        bytes32 parameters = bytes32((uint256(bitmap)) | (uint256(uint24(uint24(SPACING))) << 16));
        V1PoolKey memory key = V1PoolKey(
            V1Currency.wrap(projectIs0 ? token : quote), V1Currency.wrap(projectIs0 ? quote : token),
            hook, manager, FEE, parameters);
        manager.initialize(key, opening);
        positionId = positions.nextTokenId();
        uint160 lo = TickMath.getSqrtPriceAtTick(lower);
        uint160 hi = TickMath.getSqrtPriceAtTick(upper);
        uint256 liq = projectIs0
            ? LiquidityAmounts.getLiquidityForAmount0(lo, hi, amount)
            : LiquidityAmounts.getLiquidityForAmount1(lo, hi, amount);
        require(liq != 0 && liq <= type(uint128).max, "LIQUIDITY");
        bytes[] memory p = new bytes[](2);
        p[0] = abi.encode(key, lower, upper, uint128(liq),
            uint128(projectIs0 ? amount : 0), uint128(projectIs0 ? 0 : amount), lock, bytes(""));
        p[1] = abi.encode(key.currency0, key.currency1);
        positions.modifyLiquidities(abi.encode(hex"020d", p), deadline);
        permit2.approve(token, address(positions), 0, 0);
        IERC20(token).forceApprove(address(permit2), 0);
        uint256 residue = IERC20(token).balanceOf(address(this));
        if (residue != 0) {
            // Infinity position minting can round liquidity down by a few
            // units. Return that remainder to the launchpad rather than
            // leaving an unrecoverable balance on the bootstrapper.
            IERC20(token).safeTransfer(msg.sender, residue);
        }
        if (IERC20(token).balanceOf(address(this)) != 0) revert("RESIDUE");
        pid = keccak256(abi.encode(key));
    }
}

contracts/pancake-v1/PancakeV1InfinityTo.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
contract PancakeV1InfinityToken is ERC20 {
    uint256 public constant TOTAL_SUPPLY = 1_000_000_000 ether;
    address public immutable launchpad;
    address public immutable poolManager;
    address public immutable positionManager;
    address public immutable locker;
    address public immutable initialBuyRecipient;
    uint256 public immutable launchBlock;
    uint256 public immutable restrictionsEndBlock;
    string private _metadataURI;
    bytes32 public immutable metadataHash;
    constructor(string memory n,string memory s,string memory u,bytes32 h,address lp,address pm,address pos,
        address l,address recipient,address mintTo,uint256 blocks_) ERC20(n,s) {
        launchpad=lp; poolManager=pm; positionManager=pos; locker=l; initialBuyRecipient=recipient;
        launchBlock=block.number; restrictionsEndBlock=block.number+blocks_; _metadataURI=u; metadataHash=h;
        _mint(mintTo,TOTAL_SUPPLY);
    }
    function metadataURI() external view returns(string memory){return _metadataURI;}
    function tokenURI() external view returns(string memory){return _metadataURI;}
    function _update(address from,address to,uint256 value) internal override {
        if(restrictionsEndBlock > launchBlock && block.number<=restrictionsEndBlock&&from!=address(0)&&to!=address(0)
            &&to!=poolManager&&to!=positionManager&&to!=locker&&to!=launchpad) {
            if(from==poolManager){if(block.number==launchBlock&&to!=initialBuyRecipient)revert("LAUNCH_BLOCK");if(value>55_000_000 ether)revert("BUY_CAP");}
            if(balanceOf(to)+value>50_000_000 ether)revert("HOLD_CAP");
        }
        super._update(from,to,value);
    }
}

contracts/pancake-v1/PancakeV1Interfaces.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @notice Narrow, compatible view of the existing V5 stock registry.
/// Provenance: contracts/v5/interfaces/IPairV4.sol (ABI is intentionally
/// repeated here so this release has no runtime dependency on retired code).
interface IStockTokenRegistryV5Compatible {
    struct StockConfig {
        bool enabled;
        uint8 decimals;
        bytes32 symbol;
        address priceFeed;
        uint256 graduationTargetUsdE8;
        bool ethRouteEnabled;
    }
    function isEnabled(address token) external view returns (bool);
    function getConfig(address token) external view returns (StockConfig memory);
}

interface IPancakeV1Feed {
    function decimals() external view returns (uint8);
    function latestRoundData() external view returns (uint80,int256,uint256,uint256,uint80);
}

type V1Currency is address;
type V1PoolId is bytes32;
interface IV1Hooks {}
interface IV1PoolManager {
    function vault() external view returns (address);
    function initialize(V1PoolKey calldata key, uint160 sqrtPriceX96) external returns (int24);
}
interface IV1Vault {
    function manager() external view returns (address);
}
struct V1PoolKey {
    V1Currency currency0;
    V1Currency currency1;
    IV1Hooks hooks;
    IV1PoolManager poolManager;
    uint24 fee;
    bytes32 parameters;
}
interface IV1Permit2 {
    function approve(address token, address spender, uint160 amount, uint48 expiration) external;
    function pull(address token, address owner, address to, uint256 amount) external;
}
interface IV1CLPositionManager {
    function vault() external view returns (address);
    function clPoolManager() external view returns (IV1PoolManager);
    function permit2() external view returns (address);
    function nextTokenId() external view returns (uint256);
    function modifyLiquidities(bytes calldata payload, uint256 deadline) external payable;
}

contracts/pancake-v1/PancakeV1LaunchpadI.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {OwnableUpgradeable} from "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import {UUPSUpgradeable} from "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

interface IInfinityNftModule {
    function launchpad() external view returns (address);
    function hook() external view returns (address);
    function factory() external view returns (address);
    function launch(address creator, bytes calldata encoded) external payable returns (address token);
    function launchAndBuy(address creator, bytes calldata encoded) external payable returns (address token, uint256 output);
    function validatePool(address project, address quote, bytes32 id, uint16 weight,
        uint256 positionId, uint256 projectAmount, int24 lower, int24 upper,
        uint256 quotePriceE8, uint8 quoteDecimals) external view returns (bool);
    function validateSupply(address project) external view returns (bool);
}

interface IInfinityNftCoordinator {
    function launchpad() external view returns (address);
    function engine() external view returns (address);
}

/// @notice Thin UUPS dispatcher installed at the EXISTING launchpad proxy.
/// Legacy selectors delegatecall the PINNED prior implementation, retaining
/// its exact behavior/storage. NFT calls use ordinary calls to a new module.
/// @dev Pin the prior runtime and validate its exact layout before deployment:
/// slot 9 is _pools; slot 0x39 is _infinityEngine. No new storage is appended.
contract PancakeV1LaunchpadInfinityNftUpgradeable is OwnableUpgradeable, UUPSUpgradeable {
    using SafeERC20 for IERC20;
    address public immutable legacyImplementation;
    IInfinityNftModule public immutable nftModule;
    address public immutable nftDirectQuoteCoordinator;
    error InvalidNftRoute();

    constructor(address expectedProxy, address legacy, bytes32 legacyCodeHash,
        IInfinityNftModule module_, address coordinator)
    {
        if (expectedProxy.code.length == 0 || legacy.codehash != legacyCodeHash
            || legacyCodeHash == bytes32(0) || legacy == expectedProxy
            || address(module_).code.length == 0 || module_.launchpad() != expectedProxy
            || module_.hook() == address(0) || module_.factory() == address(0)
            || coordinator.code.length == 0
            || IInfinityNftCoordinator(coordinator).launchpad() != expectedProxy
            || IInfinityNftCoordinator(coordinator).engine() != address(module_))
            revert InvalidNftRoute();
        legacyImplementation = legacy;
        nftModule = module_;
        nftDirectQuoteCoordinator = coordinator;
        _disableInitializers();
    }

    function _authorizeUpgrade(address) internal override onlyOwner {}

    function _mode(bytes calldata encoded) private pure returns (uint256 mode) {
        if (encoded.length < 13 * 32) revert InvalidNftRoute();
        uint256 head;
        assembly { head := calldataload(encoded.offset) }
        if (head % 32 != 0 || head > encoded.length - 12 * 32) revert InvalidNftRoute();
        assembly { mode := calldataload(add(add(encoded.offset, head), 224)) }
    }

    function launchInfinity(bytes calldata encoded) external payable returns (address token) {
        uint256 mode = _mode(encoded);
        if (mode == 5) return nftModule.launch{value: msg.value}(msg.sender, encoded);
        if (mode > 4) revert InvalidNftRoute();
        _delegateLegacy();
    }

    function launchInfinityAndBuy(bytes calldata encoded) external payable {
        (bytes memory launchData, bytes memory buyPlan) = abi.decode(encoded, (bytes, bytes));
        // A buy-only call (empty launchData) is a legacy path.
        if (launchData.length != 0) {
            if (launchData.length < 13 * 32) revert InvalidNftRoute();
            uint256 mode;
            uint256 head;
            assembly { head := mload(add(launchData, 32)) }
            if (head % 32 != 0 || head > launchData.length - 12 * 32) revert InvalidNftRoute();
            assembly { mode := mload(add(add(launchData, 32), add(head, 224))) }
            if (mode == 5) {
                if (keccak256(encoded) != keccak256(abi.encode(launchData, buyPlan)))
                    revert InvalidNftRoute();
                nftModule.launchAndBuy{value: msg.value}(msg.sender, encoded);
                return;
            }
            if (mode > 4) revert InvalidNftRoute();
        }
        _delegateLegacy();
    }

    function launchInfinityNftFor(address creator, bytes calldata encoded)
        external payable returns (address token)
    {
        if (msg.sender != nftDirectQuoteCoordinator || creator == address(0)
            || _mode(encoded) != 5) revert InvalidNftRoute();
        token = nftModule.launch{value: msg.value}(creator, encoded);
    }

    /// @dev New factory mints project supply to the existing proxy because
    /// project tokens are permanently bound to that launchpad address.
    function releaseInfinityNftSupply(address project) external {
        if (msg.sender != address(nftModule) || project == address(0)
            || !nftModule.validateSupply(project)) revert InvalidNftRoute();
        IERC20 token = IERC20(project);
        uint256 supply = 1_000_000_000 ether;
        if (token.balanceOf(address(this)) != supply || token.totalSupply() != supply)
            revert InvalidNftRoute();
        token.safeTransfer(msg.sender, supply);
    }

    /// @dev Keccak mapping layout copied from the compiler-verified deployed
    /// predecessor. Only the pinned NFT module can append, and only after its
    /// registered actual manager PoolKey and factory collection checks pass.
    function recordInfinityNftPool(address project, address quote, bytes32 id, uint16 weight,
        uint256 positionId, uint256 projectAmount, int24 lower, int24 upper,
        uint256 quotePriceE8, uint8 quoteDecimals) external
    {
        if (msg.sender != address(nftModule) || project == address(0)
            || quote == address(0) || id == bytes32(0) || weight == 0 || positionId == 0
            || projectAmount == 0 || lower >= upper
            || !nftModule.validatePool(project, quote, id, weight,
                positionId, projectAmount, lower, upper, quotePriceE8, quoteDecimals))
            revert InvalidNftRoute();
        bytes32 arraySlot = keccak256(abi.encode(project, uint256(9)));
        uint256 ticks = uint256(uint24(lower)) | (uint256(uint24(upper)) << 24);
        assembly {
            let length := sload(arraySlot)
            // Five markets maximum. All destinations are fresh storage.
            if iszero(lt(length, 5)) { revert(0, 0) }
            sstore(arraySlot, add(length, 1))
            mstore(0, arraySlot)
            let base := add(keccak256(0, 32), mul(length, 7))
            sstore(base, or(shl(160, weight), quote))
            sstore(add(base, 1), id)
            sstore(add(base, 2), positionId)
            sstore(add(base, 3), projectAmount)
            sstore(add(base, 4), ticks)
            sstore(add(base, 5), quotePriceE8)
            sstore(add(base, 6), quoteDecimals)
        }
    }

    fallback() external payable { _delegateLegacy(); }
    receive() external payable { _delegateLegacy(); }

    function _delegateLegacy() private {
        address target = legacyImplementation;
        assembly {
            calldatacopy(0, 0, calldatasize())
            let ok := delegatecall(gas(), target, 0, calldatasize(), 0, 0)
            returndatacopy(0, 0, returndatasize())
            switch ok
            case 0 { revert(0, returndatasize()) }
            default { return(0, returndatasize()) }
        }
    }
}

contracts/pancake-v1/PancakeV1PermanentP.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @notice ERC721 receiver with intentionally no transfer, decrease, or
/// principal withdrawal surface. Once sent here, a position is permanent.
contract PancakeV1PermanentPositionLock {
    address public immutable positionManager;
    constructor(address manager_) { positionManager = manager_; }
    function onERC721Received(address, address, uint256, bytes calldata)
        external view returns (bytes4) {
        require(msg.sender == positionManager, "UNEXPECTED_NFT");
        return this.onERC721Received.selector;
    }
}
